def transform(grid):
    """For each 4-connected component of 1s that fully encloses at least one
    zero cavity, mark zeros 8-adjacent to the component: 3 if the zero is in
    an enclosed cavity, 2 otherwise (exterior). Components that do not enclose
    any cavity (open/leaky shapes) are left unmarked. If no component encloses
    anything, the grid is returned unchanged."""
    g=grid
    h,w=len(g),len(g[0])
    # flood zeros 4-connected from the border (1s are walls)
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in D4:
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==0 and not seen[a][b]:
                seen[a][b]=True;q.append((a,b))
    if not any(g[i][j]==0 and not seen[i][j] for i in range(h) for j in range(w)):
        return [r[:] for r in g]
    # 4-connected components of 1s
    comp=[[None]*w for _ in range(h)]; cid=0
    for i in range(h):
        for j in range(w):
