                q=deque([(i,j)]); comp[i][j]=cid
                while q:
                    a,b=q.popleft()
                    for di,dj in D4:
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w and g[x][y]==1 and comp[x][y] is None:
                            comp[x][y]=cid;q.append((x,y))
                cid+=1
    closed=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j]:
                for di,dj in D8:
                    a,b=i+di,j+dj
                    if 0<=a<h and 0<=b<w and g[a][b]==1: closed.add(comp[a][b])
